#!/usr/bin/env node

/**
 * Refresh every package's copy of data/*.json after editing the shared data.
 * Files generated by another toolchain (Dart) are regenerated when that
 * toolchain is installed; otherwise the command to run is printed.
 *
 *   pnpm data:sync
 */

import { copyFileSync, mkdirSync, readdirSync } from "fs";
import { execSync } from "child_process";
import { join } from "path";
import { pathToFileURL } from "url";
import { PRODUCTS } from "./manifest.js";
import { repoRoot } from "./paths.js";

export function dataFiles(root = repoRoot) {
  return readdirSync(join(root, "data"))
    .filter((name) => name.endsWith(".json"))
    .sort();
}

function hasCommand(command) {
  try {
    execSync(`command -v ${command}`, { stdio: "ignore", shell: "/bin/sh" });
    return true;
  } catch {
    return false;
  }
}

function main() {
  const files = dataFiles();
  for (const product of PRODUCTS) {
    for (const target of product.data) {
      if (target.kind === "copy") {
        mkdirSync(join(repoRoot, target.dir), { recursive: true });
        for (const name of files) {
          copyFileSync(join(repoRoot, "data", name), join(repoRoot, target.dir, name));
        }
        console.log(`Copied ${files.length} file(s) → ${target.dir}/`);
      } else if (target.kind === "generated") {
        const tool = target.command.split(" ")[0];
        if (hasCommand(tool)) {
          execSync(target.command, { cwd: repoRoot, stdio: "inherit" });
          console.log(`Regenerated ${target.path}`);
        } else {
          console.log(`Skipped ${target.path}: run \`${target.command}\` (${tool} not installed).`);
        }
      }
    }
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main();
}
